CREATE FUNCTION public.set_competition_notification(_competition_id uuid,_enabled boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.competitions WHERE id=_competition_id) THEN RAISE EXCEPTION 'Unknown competition'; END IF; UPDATE public.profiles SET notification_preferences=coalesce(notification_preferences,'{}'::jsonb)||jsonb_build_object('competition_alert_overrides',coalesce(notification_preferences->'competition_alert_overrides','{}'::jsonb)||jsonb_build_object(_competition_id::text,_enabled)) WHERE id=auth.uid() RETURNING notification_preferences->'competition_alert_overrides' INTO result; RETURN result; END; $$; REVOKE ALL ON FUNCTION public.set_competition_notification(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_competition_notification(uuid,boolean) TO authenticated;